#include<bits/stdc++.h>
using namespace std;
const int N=200005;

struct Point {
    int x, y;
};

int n;
Point p[N];
int tmp[N];

bool cmpX(int i, int j) {
    return p[i].x < p[j].x;
}

bool cmpY(int i, int j) {
    return p[i].y < p[j].y;
}

bool check(int d) {
    int order[N];
    for(int i = 1; i <= n; i++) order[i] = i;
    sort(order + 1, order + n + 1, cmpX);
    
    int ySet[N], yCnt = 0;
    int left = 1;
    
    for(int right = 1; right <= n; right++) {
        int idxR = order[right];
        
        while(left < right && p[order[right]].x - p[order[left]].x >= d) {
            int idxL = order[left];
            int pos = yCnt + 1;
            for(int k = 1; k <= yCnt; k++) {
                if(p[idxL].y < ySet[k]) {
                    pos = k;
                    break;
                }
            }
            for(int k = yCnt; k >= pos; k--) {
                ySet[k+1] = ySet[k];
            }
            ySet[pos] = p[idxL].y;
            yCnt++;
            left++;
        }
        
        for(int k = 1; k <= yCnt; k++) {
            if(ySet[k] >= p[idxR].y + d) {
                return true;
            }
        }
        
        for(int k = yCnt; k >= 1; k--) {
            if(ySet[k] <= p[idxR].y - d) {
                return true;
            }
        }
    }
    
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    
    cin >> n;
    for(int i = 1; i <= n; i++) {
        cin >> p[i].x >> p[i].y;
    }
    
    int left = 0, right = 1e9, ans = 0;
    while(left <= right) {
        int mid = left + (right - left) / 2;
        if(check(mid)) {
            ans = mid;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    
    cout << ans << endl;
    
    return 0;
}

